        'important_terms' => [
            ['term' => 'Delusion', 'definition' => 'A fixed false belief that is firmly maintained despite incontrovertible and obvious proof or evidence to the contrary.'],
            ['term' => 'Hallucination', 'definition' => 'A sensory perception that has the compelling sense of reality of a true perception but occurs without external stimulation of the relevant sensory organ.'],
            ['term' => 'Formal Thought Disorder', 'definition' => 'A disturbance in the organization and processing of thoughts, clinically inferred from speech patterns such as derailment, tangentiality, or loose associations.'],
            ['term' => 'Avolition', 'definition' => 'A severe lack of initiative, motivation, or capacity to initiate and persist in goal-directed activities (e.g., self-care, work, or study).']
        ]
